// Workspacer /m-next service worker (scope /m-next/; /m keeps its own).
//
// Two jobs, as for /m:
//   1. Background Web Push: the hub pushes when an agent needs you; this
//      shows it even when the app is closed. It does not keep a socket alive.
//   2. Fast, resilient load: the whole shell (modules, styles, fonts, icons)
//      is precached so the installed app opens instantly and survives a blip.
//      Navigation and modules are network-first so a new hub's client wins
//      when online. No session data is ever cached.
//
// The list and cache name below are generated by
// scripts/check-mobile-next-assets.mjs --write; the name is a content hash,
// so any asset change installs a fresh shell.

// <generated-shell>
const CACHE = 'wks-m-next-56240ca0d4a8';
const SHELL = [
  "./",
  "app.css",
  "fonts/Inter-LICENSE.txt",
  "fonts/Inter-Variable.woff2",
  "fonts/JetBrainsMono-LICENSE.txt",
  "fonts/JetBrainsMono-Variable.woff2",
  "icons.svg",
  "js/actions.js",
  "js/boot.js",
  "js/bus.js",
  "js/card.js",
  "js/fleet.js",
  "js/main.js",
  "js/markdown.js",
  "js/projects.js",
  "js/push.js",
  "js/store.js",
  "js/theme.js",
  "js/themes.js",
  "js/ui.js",
  "js/util.js",
  "js/views/briefs.js",
  "js/views/chat.js",
  "js/views/child.js",
  "js/views/gate.js",
  "js/views/history.js",
  "js/views/island.js",
  "js/views/jobs.js",
  "js/views/newagent.js",
  "js/views/nodes.js",
  "js/views/projects.js",
  "js/views/sessions.js",
  "js/views/settings.js",
  "js/views/tasks.js",
  "js/views/transcript.js",
  "manifest.webmanifest",
  "tokens.css",
];
// </generated-shell>

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL).catch(() => {})));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith('wks-m-next-') && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const scope = new URL(self.registration.scope);
  if (url.origin !== scope.origin || !url.pathname.startsWith(scope.pathname)) return;
  const nav = req.mode === 'navigate';
  const key = nav ? './' : url.pathname.slice(scope.pathname.length);
  if (!nav && !SHELL.includes(key)) return;
  const cacheKey = new URL(nav ? scope.pathname : url.pathname, scope).href;
  event.respondWith((async () => {
    const c = await caches.open(CACHE);
    if (key.startsWith('fonts/')) {
      const hit = await c.match(cacheKey);
      if (hit) return hit;
    }
    try {
      const fresh = await fetch(req);
      if (fresh.ok) c.put(cacheKey, fresh.clone());
      return fresh;
    } catch {
      return (await c.match(cacheKey)) || Response.error();
    }
  })());
});

// A push from the hub: { title, body, sessionId }.
self.addEventListener('push', (event) => {
  let data = {};
  try { data = event.data ? event.data.json() : {}; } catch (_) { /* not JSON */ }
  event.waitUntil(self.registration.showNotification(data.title || 'Workspacer', {
    body: data.body || 'An agent needs you',
    icon: '/icon-192.png',
    badge: '/icon-192.png',
    tag: data.sessionId || 'workspacer',
    renotify: true,
    data: { sessionId: data.sessionId || '' },
  }));
});

// Focus an open /m-next window (and tell it which session), or open one.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const sid = (event.notification.data && event.notification.data.sessionId) || '';
  const scope = self.registration.scope;
  event.waitUntil((async () => {
    const wins = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const c of wins) {
      if (c.url.startsWith(scope)) {
        try { await c.focus(); } catch (_) { /* not focusable */ }
        c.postMessage({ type: 'open-agent', sessionId: sid });
        return;
      }
    }
    await self.clients.openWindow(sid ? scope + '?agent=' + encodeURIComponent(sid) : scope);
  })());
});
